using System;using System.IO;using System.Threading.Tasks;using System.Windows;using CodexStrip;
class ThicknessMemoryTest {
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}
 [STAThread]static void Main(){Settings.DataDir=Path.GetFullPath("work/thickness-test-data");var app=new Application();var w=new StripWindow(true){Width=1200,Height=240};w.Config.Thicknesses.Clear();w.Loaded+=async delegate{try{await Task.Delay(150);w.TransposeView();await Task.Delay(150);Check(w.Portrait&&Math.Abs(w.Width-320)<2,"first portrait width");w.Width=360;await Task.Delay(100);w.TransposeView();await Task.Delay(150);Check(!w.Portrait&&Math.Abs(w.Height-240)<2,"restore horizontal height");w.Height=260;await Task.Delay(100);w.TransposeView();await Task.Delay(150);Check(w.Portrait&&Math.Abs(w.Width-360)<2,"restore custom portrait");w.Config.RememberThickness("other-monitor",true,420);w.Config.Save();var read=Settings.Load();Check(read.Thickness("other-monitor",true)==420&&read.Thickness(w.CurrentMonitorKey,true)==360&&read.Thickness(w.CurrentMonitorKey,false)==260,"persist independent monitor/orientation");Check(read.Thickness("new-monitor",true)==320,"new monitor default");foreach(double scale in new[]{1.0,1.25,1.5}){var source=new WindowGeometry.RECT{right=1500,bottom=(int)(240*scale)};var work=new WindowGeometry.RECT{right=2400,bottom=1800};var target=WindowGeometry.AdaptiveTranspose(source,work,(int)(320*scale),(int)(210*scale),320*scale);Check(Math.Abs((target.right-target.left)/scale-320)<1,"DPI logical thickness");}File.WriteAllText("work/thickness-memory-test.txt","PASS: first vertical 320; independent custom horizontal/vertical restoration; per-monitor persistence; new-monitor default; DPI logical width");}catch(Exception e){File.WriteAllText("work/thickness-memory-test.txt",e.ToString());}finally{w.Close();}};app.Run(w);}
}
